<script setup>
import PublicLayout from '../../../Layouts/PublicLayout.vue';
import AdminQuickLinks from '../../../Components/AdminQuickLinks.vue';
import { Head, router } from '@inertiajs/vue3';
import { ref } from 'vue';
const props=defineProps({accounts:Object,filters:Object,stats:Object}); const search=ref(props.filters?.search||''); const status=ref(props.filters?.status||'');
function filter(){router.get('/admin/dues',{search:search.value,status:status.value},{preserveState:true,replace:true});}
function bulk(){if(confirm('Send dues reminders to the selected status group?')) router.post('/admin/dues/remind-bulk',{status:status.value||'all'});}
const money=v=>'₦'+Number(v||0).toLocaleString('en-NG');
</script>
<template><PublicLayout><Head title="Membership Dues"/><section class="bg-[#00351F]"><div class="mx-auto max-w-[1400px] px-5 py-8"><p class="text-xs font-bold uppercase tracking-widest text-[#D4A72C]">Administration</p><div class="flex flex-wrap items-center justify-between gap-3"><h1 class="mt-2 text-3xl font-extrabold text-white">Membership Dues</h1><a href="/admin/dues/payments" class="rounded-lg border border-white/40 px-4 py-2 text-sm font-bold text-white hover:bg-white/10">View Payments & Reconciliation</a></div></div><AdminQuickLinks/></section><div class="mx-auto max-w-7xl px-5 py-8"><div class="flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-2xl font-extrabold text-[#00351F]">Membership Dues</h1><p class="mt-1 text-sm text-gray-500">Monitor dues obligations, collections and member payment status.</p></div><button @click="bulk" class="rounded-lg bg-[#006B3C] px-4 py-2 text-sm font-bold text-white">Send bulk reminders</button></div><div class="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-5"><div v-for="item in [{label:'Accounts',value:stats.members},{label:'Up to date',value:stats.up_to_date},{label:'Overdue',value:stats.overdue},{label:'Exempt',value:stats.exempt},{label:'Collected',value:money(stats.collected)}]" class="rounded-xl border bg-white p-4"><p class="text-xs text-gray-500">{{item.label}}</p><p class="mt-2 text-xl font-extrabold text-[#00351F]">{{item.value}}</p></div></div><div class="mt-6 flex flex-wrap gap-3"><input v-model="search" @keyup.enter="filter" placeholder="Search member" class="rounded-lg border-gray-300"/><select v-model="status" @change="filter" class="rounded-lg border-gray-300"><option value="">All statuses</option><option value="up_to_date">Up to date</option><option value="due">Due</option><option value="overdue">Overdue</option><option value="exempt">Exempt</option></select><button @click="filter" class="rounded-lg border px-4 py-2 text-sm font-bold">Filter</button></div><div class="mt-5 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-gray-50 text-gray-500"><tr><th class="p-4">Member</th><th>Plan</th><th>Commencement</th><th>Paid through</th><th>Next due</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="a in accounts.data" :key="a.id" class="border-t"><td class="p-4"><b>{{a.name}}</b><span class="block text-xs text-gray-500">{{a.email}}</span></td><td class="capitalize">{{a.plan}}</td><td>{{a.commencement_date||'—'}}</td><td>{{a.paid_through||'—'}}</td><td>{{a.next_due_at||'—'}}</td><td class="capitalize">{{a.status.replace('_',' ')}}</td><td><a :href="`/admin/dues/${a.user_id}`" class="font-bold text-[#006B3C]">Manage</a></td></tr></tbody></table><p v-if="!accounts.data.length" class="p-6 text-sm text-gray-500">No dues accounts yet. Accounts are created automatically when members visit their dues page or are managed here.</p></div></div></PublicLayout></template>
